-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.site_settings()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(
    (select jsonb_build_object(
              'hideEmptySemesters', s.hide_empty_semesters,
              'hiddenCourses', to_jsonb(s.hidden_courses),
              'updatedAt', s.updated_at,
              'updatedBy', s.updated_by)
       from public.site_settings s
      where s.id),
    jsonb_build_object(
      'hideEmptySemesters', false, 'hiddenCourses', '[]'::jsonb, 'updatedAt', null, 'updatedBy', null));
$function$;

grant execute on function public.site_settings() to service_role;
